import { MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, step, uniform, float, sub, min, add, color } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, Shape, ExtrudeGeometry, DirectionalLight } = ctx.THREE;

  // ---------- Config ----------
  const width = 2.6;
  const height = 0.68;
  const radius = 0.08;
  const depth = 0.03;
  const gradientStops = config?.intent?.visualSpec?.gradientStops ?? config.gradientStops ?? [];

  // ---------- Helper to build vertical gradient node ----------
  const buildGradientNode = (uvNode) => {
    // assume three stops, fallback to defaults
    const c0 = color(gradientStops[0]?.hex ?? '#ff4450');
    const c1 = color(gradientStops[1]?.hex ?? '#ff2a38');
    const c2 = color(gradientStops[2]?.hex ?? '#c1121f');
    const t0 = float(gradientStops[0]?.at ?? 0);
    const t1 = float(gradientStops[1]?.at ?? 0.55);
    const t2 = float(gradientStops[2]?.at ?? 1);
    const y = uvNode.y;
    const mix01 = mix(c0, c1, smoothstep(t0, t1, y));
    const final = mix(mix01, c2, smoothstep(t1, t2, y));
    return final;
  };

  // ---------- Background Plane ----------
  const bgGroup = new Group();
  const bgWidth = 7;
  const bgHeight = 6;
  const bgGeometry = new ctx.THREE.PlaneGeometry(bgWidth, bgHeight);
  const bgUV = uv();
  const bgColorNode = buildGradientNode(bgUV);
  const bgMaterial = new MeshStandardNodeMaterial();
  bgMaterial.colorNode = bgColorNode;
  bgMaterial.roughness = 0.5;
  bgMaterial.metalness = 0.0;
  const bgMesh = new Mesh(bgGeometry, bgMaterial);
  bgMesh.position.set(0, 0, -2.5);
  bgGroup.add(bgMesh);

  // ---------- Button Geometry ----------
  const shape = new Shape();
  shape.moveTo(-width / 2 + radius, -height / 2);
  shape.lineTo(width / 2 - radius, -height / 2);
  shape.absarc(width / 2 - radius, -height / 2 + radius, radius, -Math.PI / 2, 0, false);
  shape.lineTo(width / 2, height / 2 - radius);
  shape.absarc(width / 2 - radius, height / 2 - radius, radius, 0, Math.PI / 2, false);
  shape.lineTo(-width / 2 + radius, height / 2);
  shape.absarc(-width / 2 + radius, height / 2 - radius, radius, Math.PI / 2, Math.PI, false);
  shape.lineTo(-width / 2, -height / 2 + radius);
  shape.absarc(-width / 2 + radius, -height / 2 + radius, radius, Math.PI, 3 * Math.PI / 2, false);
  const extrudeSettings = {
    depth,
    bevelEnabled: true,
    bevelThickness: depth,
    bevelSize: radius,
    bevelSegments: 2,
    steps: 1,
  };
  const buttonGeometry = new ExtrudeGeometry(shape, extrudeSettings);
  buttonGeometry.translate(0, 0, -depth / 2);

  // ---------- Button Material ----------
  const emissiveIntensity = uniform(1.6);
  const edgeWidthUV = float(0.015 / width);
  const uvNode = uv();
  const gradColor = buildGradientNode(uvNode);
  const minDist = min(min(uvNode.x, sub(float(1.0), uvNode.x)), min(uvNode.y, sub(float(1.0), uvNode.y)));
  const edgeMask = step(edgeWidthUV, minDist);
  const accentCol = color('#ff2a38');
  const emissiveColor = mul(accentCol, mul(edgeMask, emissiveIntensity));

  const buttonMaterial = new MeshStandardNodeMaterial();
  buttonMaterial.colorNode = gradColor;
  buttonMaterial.emissiveNode = emissiveColor;
  buttonMaterial.roughness = 0.5;
  buttonMaterial.metalness = 0.35;
  buttonMaterial.clearcoat = 0.22;
  buttonMaterial.clearcoatRoughness = 0.25;

  const buttonMesh = new Mesh(buttonGeometry, buttonMaterial);
  buttonMesh.castShadow = true;
  buttonMesh.receiveShadow = true;

  // ---------- Text ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const labelItem = items.find(i => i.role === 'cta-label') || { text: 'BEGIN COMMISSION' };
  const captionItem = items.find(i => i.role === 'caption') || { text: 'NO DEPOSIT REQUIRED' };

  const label = ctx.fontAtlas.createText(labelItem.text, {
    fontSize: 20,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.08 * 20,
  });
  label.position.set(0, 0, depth / 2 + 0.001);

  const caption = ctx.fontAtlas.createText(captionItem.text, {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'center',
    letterSpacingPx: 0.12 * 9,
  });
  caption.position.set(0, -height / 2 - 0.25, depth / 2 + 0.001);

  // ---------- Rim Light ----------
  const rimLight = new DirectionalLight('#ff2a38', 0.8);
  rimLight.position.set(-1, -1, 2);
  rimLight.target = buttonMesh;

  // ---------- Group ----------
  const group = new Group();
  group.add(bgGroup);
  group.add(buttonMesh);
  group.add(label);
  group.add(caption);
  group.add(rimLight);

  // ---------- Animations ----------
  const timelines = [];

  // entrance weighted‑settle
  group.scale.set(1.04, 1.04, 1.04);
  const entrance = gsap.timeline({ paused: true });
  entrance.to(group.scale, {
    x: 1,
    y: 1,
    z: 1,
    duration: 0.9,
    ease: 'cubic-bezier(0.165,0.84,0.44,1)',
  });
  entrance.play();
  timelines.push(entrance);

  const hoverEnter = () => {
    const tl = gsap.timeline({ paused: true });
    tl.to(buttonMesh.position, {
      z: 0.06,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    });
    tl.to(emissiveIntensity, {
      value: 2.2,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }, 0);
    tl.play();
    timelines.push(tl);
  };
  const hoverLeave = () => {
    const tl = gsap.timeline({ paused: true });
    tl.to(buttonMesh.position, {
      z: 0,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    });
    tl.to(emissiveIntensity, {
      value: 1.6,
      duration: 0.18,
      ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
    }, 0);
    tl.play();
    timelines.push(tl);
  };
  const press = () => {
    const tl = gsap.timeline({ paused: true });
    tl.to(group.scale, {
      x: 0.97,
      y: 0.97,
      z: 0.97,
      duration: 0.12,
      ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
    });
    tl.play();
    timelines.push(tl);
  };
  const release = () => {
    const tl = gsap.timeline({ paused: true });
    tl.to(group.scale, {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.12,
      ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
    });
    tl.play();
    timelines.push(tl);
  };

  // ---------- UserData ----------
  group.userData.handlers = {
    hoverEnter,
    hoverLeave,
    press,
    release,
  };
  group.userData.cleanup = () => {
    timelines.forEach(t => t.kill());
    buttonGeometry.dispose();
    buttonMaterial.dispose();
    bgGeometry.dispose();
    bgMaterial.dispose();
    // lights and meshes are disposed by three automatically when removed
    group.traverse(child => {
      if (child.isMesh && child.geometry) child.geometry.dispose();
      if (child.isMesh && child.material) child.material.dispose();
    });
  };

  return group;
}
